/**
 * Room code helpers and invite link handling.
 *
 * The room code itself is generated by the database (see
 * `public.online_generate_join_code()`); this module only formats, validates
 * and transports it.
 */

/** The alphabet used by the server: 32 unambiguous characters. */
export const ROOM_CODE_ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ'

/** Number of characters in a room code (32^8 = 2^40 possible codes). */
export const ROOM_CODE_LENGTH = 8

/** Query parameter used by the invite link. */
export const ROOM_QUERY_PARAM = 'room'

/** Uppercases and strips everything that is not alphanumeric. */
export function normalizeRoomCode(input: string): string {
  return input.toUpperCase().replace(/[^0-9A-Z]/g, '')
}

/** True when the code has the exact server side format. */
export function isValidRoomCode(code: string): boolean {
  if (code.length !== ROOM_CODE_LENGTH) return false
  for (const character of code) {
    if (!ROOM_CODE_ALPHABET.includes(character)) return false
  }
  return true
}

/** Formats a code for humans: `ABCD1234` becomes `ABCD-1234`. */
export function formatRoomCode(code: string): string {
  if (code.length !== ROOM_CODE_LENGTH) return code
  return `${code.slice(0, 4)}-${code.slice(4)}`
}

/** Builds a shareable invite link for the deployed application. */
export function buildInviteLink(baseUrl: string, code: string): string {
  const normalized = normalizeRoomCode(code)
  const url = new URL(baseUrl)
  url.searchParams.set(ROOM_QUERY_PARAM, normalized)
  // Keep the link tidy: a stale path such as /room/X would be confusing.
  url.hash = ''
  return url.toString()
}

/**
 * Extracts a room code from an invite link.
 * Supports `?room=CODE`, `/room/CODE` and a bare code.
 */
export function parseRoomCodeFromUrl(url: string): string | null {
  let parsed: URL
  try {
    parsed = new URL(url, 'https://placeholder.invalid')
  } catch {
    return null
  }

  const fromQuery = parsed.searchParams.get(ROOM_QUERY_PARAM)
  if (fromQuery) {
    const normalized = normalizeRoomCode(fromQuery)
    if (isValidRoomCode(normalized)) return normalized
  }

  const segments = parsed.pathname.split('/').filter(Boolean)
  const last = segments[segments.length - 1]
  if (last) {
    const normalized = normalizeRoomCode(last)
    if (isValidRoomCode(normalized)) return normalized
  }

  return null
}

/** Removes control characters from a display name. */
export function stripControlCharacters(value: string): string {
  let result = ''
  for (const character of value) {
    const code = character.codePointAt(0) ?? 0
    if (code < 0x20 || code === 0x7f) continue
    result += character
  }
  return result
}

/**
 * Cleans a display name: control characters are removed, the value is
 * trimmed and truncated. A display name is never treated as an identity.
 */
export function sanitizeDisplayName(name: string): string {
  return stripControlCharacters(name).trim().slice(0, 24)
}

/** True when a display name is acceptable. */
export function isValidDisplayName(name: string): boolean {
  return sanitizeDisplayName(name).length <= 24
}

/** Creates a UUID for move idempotency, with a fallback for insecure contexts. */
export function createMoveId(): string {
  const cryptoApi = globalThis.crypto
  if (cryptoApi && typeof cryptoApi.randomUUID === 'function') {
    return cryptoApi.randomUUID()
  }
  // Fallback for non secure contexts (plain http on a LAN address).
  const bytes = new Uint8Array(16)
  if (cryptoApi && typeof cryptoApi.getRandomValues === 'function') {
    cryptoApi.getRandomValues(bytes)
  } else {
    for (let index = 0; index < bytes.length; index += 1) {
      bytes[index] = Math.floor(Math.random() * 256)
    }
  }
  bytes[6] = (bytes[6] & 0x0f) | 0x40
  bytes[8] = (bytes[8] & 0x3f) | 0x80
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}
